package dev.daubney.scrobbled.data.api

import org.junit.Assert.assertEquals
import org.junit.Test

/** Expected values were generated by the server's own `signature.sign`. */
class SignerTest {
    @Test
    fun matchesServerForUnicodeAndIgnoresFormat() {
        val params = mapOf(
            "method" to "auth.getMobileSession", "api_key" to "abc", "username" to "alice",
            "password" to "pässwörd 日本", "format" to "json",
        )
        assertEquals("1a636a75e857c12933c3b924378d49a1", Signer.sign(params, "sekret"))
    }

    @Test
    fun matchesServerForIndexedParams() {
        val params = mapOf(
            "method" to "track.scrobble", "api_key" to "k", "sk" to "s",
            "artist[0]" to "Björk", "track[0]" to "Army of Me", "timestamp[0]" to "1700000000",
        )
        assertEquals("defdc0fa2867657d22dcad075c52fe63", Signer.sign(params, "sec"))
    }

    @Test
    fun apiSigAndCallbackAreExcluded() {
        val base = mapOf("a" to "1")
        assertEquals(Signer.sign(base, "s"), Signer.sign(base + ("api_sig" to "x") + ("callback" to "y"), "s"))
    }
}
